def is_balanced_brackets(tokens):
    depth = 0
    for t in tokens:
        if t == '(':
            depth += 1
        else:
            depth -= 1
        if depth < 0:
            return False
    return depth == 0

def alternating_sum_abs_diffs(lst):
    if len(lst) < 2:
        return 0
    diffs = [abs(lst[i + 1] - lst[i]) for i in range(len(lst) - 1)]
    total = 0
    for i, d in enumerate(diffs):
        total += d if i % 2 == 0 else -d
    return total

def render_grid_row(cells, widths):
    parts = [c.ljust(w) for c, w in zip(cells, widths)]
    return "| " + " | ".join(parts) + " |"

def average_time(times):
    def to_min(t):
        h, m = t.split(':')
        return int(h)*60 + int(m)
    total = sum(to_min(t) for t in times)
    avg = total // len(times)
    return f'{avg//60:02d}:{avg%60:02d}'

def merge_char_frequencies(strings):
    res = {}
    for s in strings:
        for ch in s:
            res[ch] = res.get(ch, 0) + 1
    return res

def pad_left_to_length(lst, n, pad):
    if len(lst) >= n:
        return lst[len(lst) - n:]
    return [pad] * (n - len(lst)) + lst

def rank_percentile_of_value(nums, x):
    cnt = sum(1 for y in nums if y < x)
    return round(cnt / len(nums) * 100, 2)

def wrap_double_quotes(s):
    escaped = s.replace('"', '\\"')
