def password_excludes_username(password, username):
    if len(password) < 8:
        return False
    return username.lower() not in password.lower()

def nearest_business_day(day_num, weekend_days):
    d = day_num
    while d % 7 in weekend_days:
        d += 1
    return d

def longest_positive_run_sum(lst):
    best_len = 0
    best_sum = 0
    cur_len = 0
    cur_sum = 0
    for x in lst:
        if x > 0:
            cur_len += 1
            cur_sum += x
        else:
            if cur_len > best_len:
                best_len = cur_len
                best_sum = cur_sum
            cur_len = 0
            cur_sum = 0
    if cur_len > best_len:
        best_sum = cur_sum
    return best_sum

