def is_valid_last4_mask_match(full_number, masked):
    if len(full_number) != 16 or not full_number.isdigit():
        return False
    if len(masked) != 16:
        return False
    if masked[:12] != '*' * 12:
        return False
    return masked[12:] == full_number[12:]

def is_valid_dashed_credit_card(s):
    import re
    if not re.fullmatch(r'\d{4}-\d{4}-\d{4}-\d{4}', s):
        return False
    digits = s.replace('-', '')
    total = 0
    for i, ch in enumerate(reversed(digits)):
        d = int(ch)
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    return total % 10 == 0

def fiscal_quarter(month, fiscal_start_month):
    offset = (month - fiscal_start_month) % 12
    return offset // 3 + 1

def key_with_min_value(d):
    best = min(d.values())
    cands = [k for k, v in d.items() if v == best]
    return min(cands)

def collapse_consecutive_duplicates(lst):
    res = []
    for x in lst:
        if not res or res[-1] != x:
            res.append(x)
    return res

def group_by_remainder(lst, n):
    result = {}
    for x in lst:
        r = x % n
        result.setdefault(r, []).append(x)
    return result

def longest_alternating_substring_length(s):
    if not s:
        return 0
    best = cur = 1
    for i in range(1, len(s)):
        if s[i] != s[i - 1]:
            cur += 1
        else:
            cur = 1
        best = max(best, cur)
    return best

def format_fraction_as_mixed(numerator, denominator):
    import math
    whole = numerator // denominator
    rem = numerator % denominator
    if rem == 0:
        return str(whole)
    g = math.gcd(rem, denominator)
    rem //= g
    denominator //= g
    if whole == 0:
        return f"{rem}/{denominator}"
    return f"{whole} {rem}/{denominator}"

def is_undulating_number(n):
    s = str(abs(n))
    if len(s) < 3:
        return False
    if s[0] == s[1]:
        return False
    for i in range(2, len(s)):
        if s[i] != s[i - 2]:
            return False
    return True
